// HT-MVP-OWNER-UAT-P0-RECOVERY-01-R2 — verified build-time public feed with authorized content.
// Must be generated by an authorized build; never writes staging, production,
// repository refs, publishing providers, or any credential-bearing file.
import { mkdir, writeFile } from "node:fs/promises";
import { createHash } from "node:crypto";
import { dirname } from "node:path";
import { probePublicPublisher } from "./public-source-readonly-probe.mjs";

const output="apps/mobile/public/healthtimes-public-feed.json";
const result=await probePublicPublisher({ includeBody: true });
if(result.status!=="PROBE_SUCCEEDED_NOT_AUTHORIZED_AS_FEED" || !result.latestWithin7Days || !result.latestTwentyMetadata?.length){
  console.error("P0 verified metadata unavailable. Refusing to generate fresh-looking feed.");
  process.exit(2);
}
const generatedAt=new Date().toISOString();
const articles=result.latestTwentyMetadata.map((article)=>({
  id:article.postId,
  type:"post",
  status:"publish",
  slug:article.slug,
  link:article.canonicalUrl,
  publishedAt:article.publishedAt,
  modifiedAt:article.modifiedAt,
  title:article.title,
  categoryIds:article.categoryIds,
  publicTerms:article.publicTerms??[],
  contentBody:article.contentBody ?? null,
  excerpt:article.excerpt ?? null,
  heroMedia:article.heroMedia ?? null,
  authorName:article.authorName ?? null,
  bodyAuthority:article.contentBody ? "VERIFIED_PUBLIC_PUBLISHED" : "BLOCKED_PENDING_OWNER_CLASSIFICATION",
  authorAuthority:article.authorName ? "VERIFIED_PUBLIC_BYLINE" : "NOT_VERIFIED",
  mediaAuthority:article.heroMedia?.sourceUrl ? "VERIFIED_PUBLIC_MEDIA" : "NOT_VERIFIED"
}));
const payload=JSON.stringify(articles);
const manifest={
  schemaVersion:1,
  source:"healthtimes.co.zw/public-wordpress-rest-metadata",
  verifiedAt:generatedAt,
  publicationDateAtLatest:result.latestPublicCandidateAt,
  freshnessSlaVerified:true,
  metadataOnly:false,
  contentBodyAvailable:true,
  restrictedBodiesIncluded:false,
  contentHashSha256:createHash("sha256").update(payload).digest("hex"),
  count:articles.length,
  articles
};
await mkdir(dirname(output),{recursive:true});
await writeFile(output,JSON.stringify(manifest,null,2)+"\n",{mode:0o644});
console.log(JSON.stringify({
  source:manifest.source,output,verifiedAt:generatedAt,latest:manifest.publicationDateAtLatest,
  records:manifest.count,hash:manifest.contentHashSha256,
  fullArticleBodies:Boolean(articles.some(a=>a.contentBody)),
  independentPremiumClassification:false,
  reader15MinuteSla:true,authorization:"NOT_DEPLOYED"
},null,2));
